class Solution:
    def getEncryptedString(self, s: str, k: int) -> str:
        n = len(s)
        encrypted_chars = []
        for i in range(n):
            # The k-th character after the character at index i
            # is at index (i + k) in a 0-indexed string.
            # Since the string is cyclic, we use modulo n.
            target_index = (i + k) % n
            encrypted_chars.append(s[target_index])
