        n = len(s)
        if n < 2:
            return False

        # Generate all substrings of length 2 from s
        substrings = set()
        for i in range(n - 1):
            substrings.add(s[i:i+2])

        # Check if any of these substrings exists in the reverse of s
        s_rev = s[::-1]
        for sub in substrings:
