from typing import List

class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # The snake starts at cell 0.
        # In an n x n grid with row-major indexing (grid[i][j] = i * n + j),
        # cell 0 corresponds to row 0, column 0.
        row, col = 0, 0

        for command in commands:
            if command == "UP":
                row -= 1
            elif command == "DOWN":
                row += 1
            elif command == "LEFT":
                col -= 1
            elif command == "RIGHT":
                col += 1

        # Calculate the final cell index using the formula: index = row * n + col
        return row * n + col
