class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        # Iterate through all possible starting positions for the first subarray
        # The first subarray ends at i + k - 1, the second at i + 2k - 1
        # So the maximum i is n - 2k
        for i in range(n - 2 * k + 1):
            # Check if the first subarray nums[i : i+k] is strictly increasing
            is_first_inc = True
            for j in range(i, i + k - 1):
                if nums[j] >= nums[j + 1]:
                    is_first_inc = False
                    break

            if is_first_inc:
                # Check if the second subarray nums[i+k : i+2*k] is strictly increasing
                is_second_inc = True
                for j in range(i + k, i + 2 * k - 1):
                    if nums[j] >= nums[j + 1]:
                        is_second_inc = False
                        break

                if is_second_inc:
                    return True

