from typing import List
import heapq

class Solution:
    def findMaxSum(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        n = len(nums1)
        answer = [0] * n

        for i in range(n):
            # Find all indices j where nums1[j] < nums1[i]
            qualifying_indices = [j for j in range(n) if nums1[j] < nums1[i]]

            # Get corresponding nums2 values
            nums2_values = [nums2[j] for j in qualifying_indices]

            # If fewer than k values available, take all
            if len(nums2_values) <= k:
                answer[i] = sum(nums2_values)
            else:
                # Use a min-heap to keep track of the k largest values
                # We'll use negative values to simulate max-heap behavior
                heap = []
                for val in nums2_values:
                    if len(heap) < k:
                        heapq.heappush(heap, -val)
                    else:
                        if -val > heap[0]:
                            heapq.heapreplace(heap, -val)

                answer[i] = sum(-x for x in heap)

        return answer
```

